import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

export default function CreateDeliveryForm() {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    customerId: "",
    deliveryAddress: "",
    status: "Assigned",
  });

  const [message, setMessage] = useState("");

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const geocodeAddress = async (address: string) => {
    const encoded = encodeURIComponent(address);
    const apiKey = process.env.REACT_APP_GOOGLE_MAPS_API_KEY;
    const url = `https://maps.googleapis.com/maps/api/geocode/json?address=${encoded}&key=${apiKey}`;
    const res = await axios.get(url);
    if (res.data.status === "OK") {
      const { lat, lng } = res.data.results[0].geometry.location;
      return { lat, lng };
    } else {
      throw new Error("Address could not be geocoded");
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const coords = await geocodeAddress(form.deliveryAddress);

      const response = await axios.post("http://localhost:5000/api/delivery", {
        customerId: form.customerId,
        location: coords,
        status: form.status,
      });

      setMessage("✅ Delivery created successfully!");
      setTimeout(() => navigate("/"), 1500);
    } catch (err: any) {
      console.error("❌ Error:", err.message || err);
      setMessage("❌ Failed to create delivery. " + err.message);
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ maxWidth: "400px", margin: "auto", padding: "20px" }}>
      <h2>Create Delivery</h2>

      <input
        type="text"
        name="customerId"
        placeholder="Customer ID"
        value={form.customerId}
        onChange={handleChange}
        required
        style={{ padding: "10px", marginBottom: "10px", width: "100%" }}
      />

      <input
        type="text"
        name="deliveryAddress"
        placeholder="Delivery Address"
        value={form.deliveryAddress}
        onChange={handleChange}
        required
        style={{ padding: "10px", marginBottom: "10px", width: "100%" }}
      />

      <select name="status" value={form.status} onChange={handleChange} style={{ padding: "10px", width: "100%", marginBottom: "10px" }}>
        <option value="Assigned">Assigned</option>
        <option value="Pending">Pending</option>
        <option value="In Transit">In Transit</option>
        <option value="Delivered">Delivered</option>
      </select>

      <button type="submit" style={{ padding: "10px", width: "100%", backgroundColor: "#007bff", color: "white", border: "none" }}>
        Create Delivery
      </button>

      {message && <p style={{ marginTop: "10px", color: message.includes("✅") ? "green" : "red" }}>{message}</p>}
    </form>
  );
}
